import requests
from collections.abc import Iterable

class ProxyIterable:
    def __getattr__(self, name):
        if name == "__iter__":
            return iter([1, 2, 3])
        raise AttributeError(name)

def test_proxy_iterable():
    data = ProxyIterable()
    # This should be detected as a stream in prepare_body
    # If it's NOT detected as a stream, it might be treated as a simple object
    # or cause an error depending on how it's handled.

    # We can check if it's treated as a stream by looking at the PreparedRequest
    req = requests.Request('POST', 'http://httpbin.org/post', data=data)
    prep = req.prepare()

    # If it's a stream, body should be the object itself, not a string representation
    # and length should be calculated if possible.
    print(f"Body type: {type(prep.body)}")
    assert prep.body is data, "Data should be treated as a stream"

if __name__ == "__main__":
    try:
        test_proxy_iterable()
        print("Success: ProxyIterable treated as stream")
    except Exception as e:
        print(f"Failure: {e}")
        exit(1)

